const fs = require('fs')
const files = {"courses": "", "quiz": "", "sidebar": "", "adminapp": ""}
fs.writeFileSync('src/admin/pages/AdminCourses.jsx', Buffer.from(files.courses, 'base64').toString('utf8'))
fs.writeFileSync('src/admin/pages/AdminQuizQuestions.jsx', Buffer.from(files.quiz, 'base64').toString('utf8'))
fs.writeFileSync('src/components/layout/Sidebar.jsx', Buffer.from(files.sidebar, 'base64').toString('utf8'))
fs.writeFileSync('src/admin/AdminApp.jsx', Buffer.from(files.adminapp, 'base64').toString('utf8'))
console.log('All 4 files written successfully')
